class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Solution:
    def minValidStrings(self, words, target):
        # Build Trie with every possible prefix from words
        root = TrieNode()
        for word in words:
            node = root
            for c in word:
                if c not in node.children:
                    node.children[c] = TrieNode()
                node = node.children[c]
                # Mark every prefix as valid end
                node.is_end = True

        from functools import lru_cache

        n = len(target)
        INF = float('inf')

        @lru_cache(None)
        def dfs(i):
            # Base: reached end of target
            if i == n:
                return 0
            res = INF
            node = root
            # Try all possible prefixes starting at i
            for j in range(i, n):
                c = target[j]
                if c not in node.children:
                    break
                node = node.children[c]
                if node.is_end:
                    count = dfs(j+1)
                    if count != INF:
                        res = min(res, 1 + count)
            return res

        ans = dfs(0)
        return -1 if ans == INF else ans
